  ),
  (
    'wf_seed_customer_story_card',
    'Customer Story Card',
    'Turn a customer quote into a testimonial card for the site and socials. The quote is set as live text afterwards, so the workflow renders the backdrop and treatment only — upload the customer''s headshot and it is composited in at lower right.',
    5,
    '{"version":1,"id":"wf_seed_customer_story_card","name":"Customer Story Card","directoryPath":"cloud:wf_seed_customer_story_card","nodes":[{"id":"prompt-1","type":"prompt","position":{"x":50,"y":130},"data":{"prompt":"Art-direct a testimonial card built around one customer quote.\n\nQuote: \"We closed the quarter four days early. The reconciliation just wasn''t a task any more.\"\nSaid by: a VP of Finance at a 400-person logistics company.\nThe result it points at: month-end close went from nine days to five.\n\nWrite one image prompt for the card''s backdrop and treatment. Hold to these:\n- The quote is set as live text later — do NOT render any words in the image\n- Leave the left two thirds quiet and uncluttered for that text\n- The attached headshot sits at lower right; keep that corner clear and lit to match\n- A calm, credible backdrop: soft depth, a suggestion of an office interior thrown far out of focus\n- Deep green accent against warm grey, nothing brighter than the headshot"},"style":{"width":320,"height":220}},{"id":"imageInput-1","type":"imageInput","position":{"x":50,"y":420},"data":{"image":null,"filename":null,"dimensions":null},"style":{"width":300,"height":280}},{"id":"llmGenerate-1","type":"llmGenerate","position":{"x":430,"y":60},"data":{"inputPrompt":null,"inputImages":[],"outputText":null,"provider":"google","model":"gemini-3-flash-preview","temperature":0.7,"maxTokens":8192,"status":"idle","error":null},"style":{"width":320,"height":360}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":810,"y":250},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"1:1","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"output-1","type":"output","position":{"x":1190,"y":240},"data":{"image":null},"style":{"width":320,"height":320}}],"edges":[{"id":"edge-prompt-1-llmGenerate-1","source":"prompt-1","sourceHandle":"text","target":"llmGenerate-1","targetHandle":"text"},{"id":"edge-llmGenerate-1-nanoBanana-1","source":"llmGenerate-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-imageInput-1-nanoBanana-1","source":"imageInput-1","sourceHandle":"image","target":"nanoBanana-1","targetHandle":"image"},{"id":"edge-nanoBanana-1-output-1","source":"nanoBanana-1","sourceHandle":"image","target":"output-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  ),
  (
    'wf_seed_integration_diagram',
    'Integration Diagram',
    'Illustrate where your product sits between the tools a team already runs — what flows in, what flows out, and the job it does in the middle. Renders an abstract diagram with empty label positions, so real logos and words are placed over it afterwards.',
    4,
    '{"version":1,"id":"wf_seed_integration_diagram","name":"Integration Diagram","directoryPath":"cloud:wf_seed_integration_diagram","nodes":[{"id":"prompt-1","type":"prompt","position":{"x":50,"y":200},"data":{"prompt":"Art-direct an illustration of where this product sits between the tools a team already runs.\n\nThe product: a revenue data layer.\nWhat flows in, and from where: raw events from the CRM, the billing system and the product database.\nWhat flows out, and to where: one agreed set of numbers, into the BI tool and the finance team''s spreadsheets.\nThe job it does in the middle: settles which number is the real one before anybody argues about it.\n\nWrite one image prompt. Hold to these:\n- Abstract and diagrammatic, not a real architecture diagram and not a screenshot\n- No text, no logos, no third-party brand marks — those are placed as real assets later\n- Three inputs converging left, one clean output leaving right; the convergence is the whole idea\n- Flat shapes, isometric hint, a single saturated accent for the centre against cool greys\n- Leave six empty label positions — three left, one centre, two right"},"style":{"width":320,"height":220}},{"id":"llmGenerate-1","type":"llmGenerate","position":{"x":430,"y":130},"data":{"inputPrompt":null,"inputImages":[],"outputText":null,"provider":"google","model":"gemini-3-flash-preview","temperature":0.7,"maxTokens":8192,"status":"idle","error":null},"style":{"width":320,"height":360}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":810,"y":160},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"16:9","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"output-1","type":"output","position":{"x":1190,"y":150},"data":{"image":null},"style":{"width":320,"height":320}}],"edges":[{"id":"edge-prompt-1-llmGenerate-1","source":"prompt-1","sourceHandle":"text","target":"llmGenerate-1","targetHandle":"text"},{"id":"edge-llmGenerate-1-nanoBanana-1","source":"llmGenerate-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-nanoBanana-1-output-1","source":"nanoBanana-1","sourceHandle":"image","target":"output-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  ),
  (
    'wf_seed_ad_creative_set',
    'Ad Creative Set',
    'One offer, three angles — pain, outcome and proof — rendered at 4:5 for a paid social test. Three separate prompts rather than one brief fanned out: three samples of a single prompt vary by seed and test the model, not the message.',
    7,
    '{"version":1,"id":"wf_seed_ad_creative_set","name":"Ad Creative Set","directoryPath":"cloud:wf_seed_ad_creative_set","nodes":[{"id":"prompt-1","type":"prompt","position":{"x":50,"y":60},"data":{"prompt":"ANGLE 1 — the pain.\n\nFor a paid social test for an incident-response tool sold to platform teams.\n\nAn abstract illustration of a night-time escalation: too many alerts arriving at once, nobody sure which one matters. Tense, congested, effortful — conveyed through composition and colour, never through a face. No text, no logos, no UI, no fake dashboards. Flat vector with soft gradients, alarm red against deep slate. 4:5 feed card, lower third left empty for a headline."},"style":{"width":320,"height":220}},{"id":"prompt-2","type":"prompt","position":{"x":50,"y":400},"data":{"prompt":"ANGLE 2 — the outcome.\n\nSame product, sold on the after rather than the before.\n\nAn abstract illustration of one clear signal where the noise used to be: a single resolved path, everything else quiet. Open, unhurried, a night that stayed uneventful. No text, no logos, no UI, no fake dashboards. Same flat vector rendering as the pain variant, same deep slate, with the red reduced to one small settled accent so the set reads as one campaign. 4:5, lower third empty."},"style":{"width":320,"height":220}},{"id":"prompt-3","type":"prompt","position":{"x":50,"y":740},"data":{"prompt":"ANGLE 3 — the proof.\n\nSame product, sold on evidence.\n\nAn abstract illustration of several on-call teams converging on one agreed timeline of what happened. Credible and quiet rather than energetic. No text, no logos, no UI, and no invented numbers, charts or metrics. Same flat vector rendering and palette as the other two variants. 4:5, lower third empty."},"style":{"width":320,"height":220}},{"id":"nanoBanana-1","type":"nanoBanana","position":{"x":450,"y":30},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-2","type":"nanoBanana","position":{"x":450,"y":370},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"nanoBanana-3","type":"nanoBanana","position":{"x":450,"y":710},"data":{"inputImages":[],"inputPrompt":null,"outputImage":null,"aspectRatio":"4:5","resolution":"1K","model":"nano-banana-pro","useGoogleSearch":false,"useImageSearch":false,"status":"idle","error":null,"imageHistory":[],"selectedHistoryIndex":0},"style":{"width":300,"height":300}},{"id":"outputGallery-1","type":"outputGallery","position":{"x":850,"y":340},"data":{"images":[],"videos":[]},"style":{"width":420,"height":400}}],"edges":[{"id":"edge-prompt-1-nanoBanana-1","source":"prompt-1","sourceHandle":"text","target":"nanoBanana-1","targetHandle":"text"},{"id":"edge-prompt-2-nanoBanana-2","source":"prompt-2","sourceHandle":"text","target":"nanoBanana-2","targetHandle":"text"},{"id":"edge-prompt-3-nanoBanana-3","source":"prompt-3","sourceHandle":"text","target":"nanoBanana-3","targetHandle":"text"},{"id":"edge-nanoBanana-1-outputGallery-1","source":"nanoBanana-1","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-2-outputGallery-1","source":"nanoBanana-2","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"},{"id":"edge-nanoBanana-3-outputGallery-1","source":"nanoBanana-3","sourceHandle":"image","target":"outputGallery-1","targetHandle":"image"}],"edgeStyle":"curved"}'::jsonb
  )
  ) as s(id, name, description, node_count, workflow_json)
